		t.Fatalf("expanded=%+v err=%v", expanded, err)
	}
}

type cancelTranscriptReader struct {
	cancel    context.CancelFunc
	remaining int
}

func (r *cancelTranscriptReader) Read(p []byte) (int, error) {
	if r.remaining == 0 {
		return 0, io.EOF
	}
	n := len(p)
	if n > r.remaining {
		n = r.remaining
	}
	for i := range p[:n] {
		p[i] = 'x'
	}
	r.remaining -= n
	r.cancel()
	return n, nil
}
